<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api, apiErrorMessage } from '../api'
import PlatformAdminNav from '../components/platform-admin/PlatformAdminNav.vue'
import type { Machine, MachineInput, MachinePlayer, SubAccount } from '../types/platformAdmin'

const machines = ref<Machine[]>([])
const subAccounts = ref<SubAccount[]>([])
const players = ref<MachinePlayer[]>([])
const loading = ref(true)
const busy = ref(false)
const error = ref('')
const feedback = ref('')
const formOpen = ref(false)
const playersOpen = ref(false)
const editingId = ref<number | null>(null)
const currentUser = ref('超级管理员')
const form = reactive<MachineInput>({ username: '', rawPassword: '', displayName: '', groupId: null, score: 0, expiresAt: null, boardOpen: true, robotManage: false, chaseEnabled: false, botCount: 0, closeSeconds: 0, cancelSeconds: 0, rebateRate: 0, oddsRate: 0, specialRebateRate: 0, specialOddsRate: 0, totalLimit: 0, positiveLimit: 0, angleLimit: 0, strictLimit: 0, tongLimit: 0, carLimit: 0, specialLimit: 0, oddEvenLimit: 0, bigSmallLimit: 0, fanLimit: 0, addLimit: 0, playerMaxStake: 0, playerMinStake: 0, games: ['AU8'] })
async function load() { loading.value = true; error.value = ''; try { const user = await api.me(); currentUser.value = user.displayName || user.username; machines.value = await api.listMachines(); subAccounts.value = user.permissions.includes('SUB_ACCOUNT_MANAGE') ? await api.listSubAccounts() : [] } catch (cause) { error.value = apiErrorMessage(cause, '机器管理加载失败') } finally { loading.value = false } }
function resetForm() { Object.assign(form, { username: '', rawPassword: '', displayName: '', groupId: null, score: 0, expiresAt: null, boardOpen: true, robotManage: false, chaseEnabled: false, botCount: 0, closeSeconds: 0, cancelSeconds: 0, rebateRate: 0, oddsRate: 0, specialRebateRate: 0, specialOddsRate: 0, totalLimit: 0, positiveLimit: 0, angleLimit: 0, strictLimit: 0, tongLimit: 0, carLimit: 0, specialLimit: 0, oddEvenLimit: 0, bigSmallLimit: 0, fanLimit: 0, addLimit: 0, playerMaxStake: 0, playerMinStake: 0, games: ['AU8'] }) }
function openCreate() { editingId.value = null; resetForm(); formOpen.value = true }
function openEdit(row: Machine) { editingId.value = row.id; Object.assign(form, { ...row, username: row.accountUsername, rawPassword: '', displayName: row.displayName, groupId: row.groupId, games: ['AU8'] }); formOpen.value = true }
async function submit() { if (!form.username.trim()) return; busy.value = true; error.value = ''; try { const payload = { ...form, username: form.username.trim(), displayName: form.displayName.trim() }; if (editingId.value) await api.updateMachine(editingId.value, payload); else await api.createMachine(payload); feedback.value = editingId.value ? '机器账号已更新' : '机器账号已创建'; formOpen.value = false; await load() } catch (cause) { error.value = apiErrorMessage(cause, '机器账号保存失败') } finally { busy.value = false } }
async function toggle(row: Machine) { busy.value = true; try { await api.changeMachineStatus(row.id, row.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE'); await load() } catch (cause) { error.value = apiErrorMessage(cause, '机器状态更新失败') } finally { busy.value = false } }
async function remove(row: Machine) {
  if (!window.confirm(`确定将[${row.accountUsername}]删除么?`)) return
  busy.value = true
  error.value = ''
  try {
    await api.deleteMachine(row.id)
    feedback.value = '机器账号已删除'
    await load()
  } catch (cause) {
    error.value = apiErrorMessage(cause, '机器账号删除失败')
  } finally {
    busy.value = false
  }
}
async function showPlayers(row: Machine) { playersOpen.value = true; players.value = []; try { players.value = await api.listMachinePlayers(row.id) } catch (cause) { error.value = apiErrorMessage(cause, '玩家列表加载失败') } }
function time(value: string | null) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '未设置' }
onMounted(() => { void load() })
</script>

<template>
  <main class="platform-admin-page"><PlatformAdminNav :display-name="currentUser" /><section class="content"><header><div><h1>机器管理</h1><p>对应 BY220 admin.php - 机器管理</p></div><button type="button" @click="openCreate">添加</button></header><p v-if="error" class="alert">{{ error }}</p><p v-if="feedback" class="feedback">{{ feedback }}</p><div v-if="loading" class="empty">正在加载...</div><div v-else class="table-wrap"><table><thead><tr><th>账户</th><th>密码</th><th>失效日期</th><th>子账号</th><th>积分</th><th>状态</th><th>开盘</th><th>托数量</th><th>封盘</th><th>取消</th><th>返水</th><th>赔率</th><th>总限额</th><th>玩家/托</th><th>操作</th></tr></thead><tbody><tr v-for="row in machines" :key="row.id"><td>{{ row.accountUsername }}</td><td>******</td><td>{{ time(row.expiresAt) }}</td><td>{{ row.groupUsername || '未设置' }}</td><td>{{ row.score.toFixed(2) }}</td><td>{{ row.status === 'ACTIVE' ? '正常' : '停用' }}</td><td>{{ row.boardOpen ? '开盘' : '闭盘' }}</td><td>{{ row.requestedBotCount }}</td><td>{{ row.closeSeconds }}</td><td>{{ row.cancelSeconds }}</td><td>{{ row.rebateRate }}</td><td>{{ row.oddsRate }}</td><td>{{ row.totalLimit.toFixed(2) }}</td><td>{{ row.normalCount }} / {{ row.botCount }}</td><td><div class="actions"><button type="button" @click="openEdit(row)">编辑</button><button type="button" @click="showPlayers(row)">玩家</button><button type="button" @click="toggle(row)">{{ row.status === 'ACTIVE' ? '停用' : '启用' }}</button><button type="button" class="danger" @click="remove(row)">删除</button></div></td></tr></tbody></table></div></section><div v-if="formOpen" class="modal-mask" @click.self="formOpen = false"><form class="modal" @submit.prevent="submit"><header><h2>{{ editingId ? '编辑机器账号' : '添加机器账号' }}</h2><button type="button" @click="formOpen = false">×</button></header><div class="form-grid"><label>用户名<input v-model="form.username" :disabled="Boolean(editingId)" required /></label><label>密码<input v-model="form.rawPassword" type="password" :required="!editingId" placeholder="编辑时留空表示不修改" /></label><label>展示名<input v-model="form.displayName" /></label><label>积分<input v-model.number="form.score" type="number" min="0" step="0.01" /></label><label>失效时间<input v-model="form.expiresAt" type="datetime-local" max="2038-01-18T00:00" /></label><label>所属子账号<select v-model="form.groupId"><option :value="null">未设置</option><option v-for="group in subAccounts" :key="group.id" :value="group.id">{{ group.username || group.displayName }}</option></select></label><label>托数量<input v-model.number="form.botCount" type="number" min="0" /></label><label>封盘秒数<input v-model.number="form.closeSeconds" type="number" min="0" /></label><label>取消秒数<input v-model.number="form.cancelSeconds" type="number" min="0" /></label><label>返水<input v-model.number="form.rebateRate" type="number" step="0.01" /></label><label>赔率<input v-model.number="form.oddsRate" type="number" step="0.01" /></label><label>特码返水<input v-model.number="form.specialRebateRate" type="number" step="0.01" /></label><label>特码赔率<input v-model.number="form.specialOddsRate" type="number" step="0.01" /></label><label>单场总限额<input v-model.number="form.totalLimit" type="number" step="0.01" /></label><label>正限额<input v-model.number="form.positiveLimit" type="number" step="0.01" /></label><label>角限额<input v-model.number="form.angleLimit" type="number" step="0.01" /></label><label>念限额<input v-model.number="form.strictLimit" type="number" step="0.01" /></label><label>通限额<input v-model.number="form.tongLimit" type="number" step="0.01" /></label><label>车限额<input v-model.number="form.carLimit" type="number" step="0.01" /></label><label>单码限额<input v-model.number="form.specialLimit" type="number" step="0.01" /></label><label>单双限额<input v-model.number="form.oddEvenLimit" type="number" step="0.01" /></label><label>大小限额<input v-model.number="form.bigSmallLimit" type="number" step="0.01" /></label><label>番限额<input v-model.number="form.fanLimit" type="number" step="0.01" /></label><label>加限额<input v-model.number="form.addLimit" type="number" step="0.01" /></label><label>玩家最高注额<input v-model.number="form.playerMaxStake" type="number" step="0.01" /></label><label>玩家最小注额<input v-model.number="form.playerMinStake" type="number" step="0.01" /></label><label class="check"><input v-model="form.boardOpen" type="checkbox" />开盘</label><label class="check"><input v-model="form.robotManage" type="checkbox" />机器人权限</label><label class="check"><input v-model="form.chaseEnabled" type="checkbox" />开通追</label></div><footer><button type="button" @click="formOpen = false">取消</button><button type="submit" :disabled="busy">{{ busy ? '保存中...' : '确认' }}</button></footer></form></div><div v-if="playersOpen" class="modal-mask" @click.self="playersOpen = false"><section class="modal players"><header><h2>玩家列表</h2><button type="button" @click="playersOpen = false">×</button></header><table><thead><tr><th>昵称</th><th>会员编号</th><th>类型</th><th>余额</th><th>状态</th></tr></thead><tbody><tr v-for="p in players" :key="p.userId"><td>{{ p.displayName }}</td><td>{{ p.memberCode }}</td><td>{{ p.playerKind }}</td><td>{{ p.balance.toFixed(2) }}</td><td>{{ p.accountStatus }}</td></tr><tr v-if="players.length===0"><td colspan="5">暂无玩家</td></tr></tbody></table></section></div></main>
</template>

<style scoped>
.platform-admin-page { min-height:100vh; background:#eaf4fb; color:#1d1d1d; }.content { padding:14px; }.content>header { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }.content h1 { margin:0; font-size:24px; }.content p { color:#5f7280; }.content>header button,.actions button,.modal footer button { padding:7px 12px; border:0; background:#1f7fb1; color:#fff; cursor:pointer; }.table-wrap { overflow:auto; border:1px solid #bcdcef; background:#fff; } table { width:100%; min-width:1550px; border-collapse:collapse; font-size:12px; } th { padding:9px; background:#40b2db; color:#fff; } td { padding:8px; border-bottom:1px solid #d9e3e8; text-align:center; }.actions { display:flex; gap:5px; }.actions button.danger { background:#d65a4a; }.alert { padding:10px; background:#ffe1de; }.feedback { padding:10px; background:#dff1e4; }.empty { padding:30px; background:#fff; text-align:center; }.modal-mask { position:fixed; inset:0; display:grid; place-items:center; background:rgba(0,0,0,.35); z-index:20; }.modal { width:min(960px,calc(100vw - 24px)); max-height:90vh; overflow:auto; background:#fff; }.modal header,.modal footer { display:flex; justify-content:space-between; padding:12px 16px; background:#eef6fb; }.modal footer { justify-content:flex-end; gap:8px; background:#fff; }.form-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; padding:16px; }.form-grid label { display:grid; gap:4px; font-size:13px; }.form-grid input,.form-grid select { padding:7px; border:1px solid #a8c8dc; min-width:0; }.form-grid .check { display:flex; align-items:center; gap:6px; }.players { width:min(760px,calc(100vw - 24px)); }.players table { min-width:0; }
@media (max-width:900px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}}
</style>

